import{Z as o,Q as i,j as r,g as t,n,o as l}from"./chunks/framework.CNW5BFKi.js";const p=JSON.parse('{"title":"趣闻轶事","description":"","frontmatter":{"layout":"gallery"},"headers":[],"relativePath":"stories/index.md","filePath":"stories/index.md"}'),g={name:"stories/index.md"},_=Object.assign(g,{setup(m){const a=[{title:"最年长完赛者",content:"100岁的福雅·辛格曾在2013年以101岁高龄完成香港马拉松，成为史上最年长的马拉松完赛者。",image:"/images/stories/oldest-runner.jpg"},{title:"最有趣的装扮",content:"许多跑者会以奇装异服参加马拉松，创造各种趣味纪录，比如最快的蝙蝠侠、最快的消防员等。",image:"/images/stories/costume-run.jpg"},{title:"赤脚夺金",content:"1960年罗马奥运会，埃塞俄比亚选手阿贝贝·比基拉赤脚跑完全程，以2小时15分16秒夺得金牌，震惊世界。四年后的东京奥运会，他在手术后仅40天便再次夺冠。",image:"/images/stories/barefoot-gold.jpg"},{title:"首位正式参赛的女性",content:'1967年波士顿马拉松，凯瑟琳·斯威策以"K.V. Switzer"报名参赛，成为首位正式获得号码布的女性跑者。赛中赛事总监试图将她拽出赛道，但她在男友的护送下坚持完赛，此后推动了女性正式参赛的进程。',image:"/images/stories/first-woman.jpg"},{title:"推着跑的父亲",content:"迪克·霍伊特推着患有脑瘫的儿子里克·霍伊特，父子二人共同完成了超过1000场耐力赛事，包括32次波士顿马拉松。他们的故事成为马拉松精神最感人的注脚。",image:"/images/stories/hoyt-father-son.jpg"},{title:"心碎坡的由来",content:'波士顿马拉松32公里处的"心碎坡"（Heartbreak Hill）得名于1936年。当时卫冕冠军约翰尼·凯利在此超越对手后拍了拍他的肩膀，对手受此激励反超夺冠，凯利"心碎"落败，这个称呼从此沿用至今。',image:"/images/stories/heartbreak-hill.jpg"},{title:"马拉松距离的由来",content:"1908年伦敦奥运会，为让英国皇室从温莎城堡阳台观看起跑，起点设在了城堡幼儿园门口，终点在白城体育场的皇室包厢前，恰好是42.195公里。此后这个距离成为马拉松的标准距离，沿用至今。",image:"/images/stories/distance-origin.jpg"}];return(c,e)=>{const s=o("StoryCollage");return i(),r("div",null,[e[0]||(e[0]=t("h1",{id:"趣闻轶事",tabindex:"-1"},[n("趣闻轶事 "),t("a",{class:"header-anchor",href:"#趣闻轶事","aria-label":'Permalink to "趣闻轶事"'},"​")],-1)),l(s,{stories:a})])}}});export{p as __pageData,_ as default};
